typedef unsigned long long uint64;
#define NULL 0
#define MAX_DIRECTORY_LENGTH 64
#define FILE_MANAGER_CACHE_EXTENSION ".ps2fmc"

class string_buf;
class stringx
{
  friend class string_buf;
  protected:
    char *chars;
    string_buf *my_buf;
  public:
    stringx();
    stringx(const stringx &cp);
    stringx(const char *str, int len = -1);
    ~stringx();
    stringx &operator+=(const stringx &cp);
    stringx &operator+=(const char *str);
};

#define PSTRING_PCHUNK_NUMBER 4
class pstring
{
  private:
    uint64 pchunk[PSTRING_PCHUNK_NUMBER];
  public:
    const char * c_str() const;
};

struct sceCdlFILE
{
  unsigned int lsn;
  unsigned int size;
  char name[16];
};

class os_file
{
  public:
    enum mode_flags
    {
      FILE_READ   = 1,
      FILE_WRITE  = 2,
      FILE_MODIFY = 3,
      FILE_APPEND = 4
    };
    os_file();
    ~os_file();
    void open(const stringx & _name, int _flags);
    void close();
    inline bool is_open() const { return opened; }
  private:
    stringx name;
    int   flags;
    bool  opened;
    bool  eof;
    bool  from_cd;
    union
    {
      int host;
      sceCdlFILE cd;
    } io;
    int curr_fp;
};

template <class T> class AvlTree;
template <class T>
class TreeNode
{
protected:
  friend class AvlTree<T>;
  TreeNode *l;
  TreeNode *r;
  TreeNode *p;
  T *d;
  char h;
public:
  TreeNode *parent() { return (p); }
  TreeNode *left() { return (l); }
  TreeNode *right() { return (r); }
  T *data() { return (d); }
  char height() { return(h); }
};

template <class T>
class AvlTree
{
protected:
  typedef TreeNode<T> TNode;
  TNode *rootNode;
  int s;
  char disposeElements;
public:
  TNode *root() { return (rootNode); }
};

class singleton
{
  protected:
    singleton() {}
    virtual ~singleton() {}
  private:
    singleton(const singleton&);
    singleton& operator=(const singleton&);
};

class file_info_node;
class path_info_node;
class stash { char data[56]; };
extern void error(const char *fmt, ...);

class file_manager : public singleton
{
  public:
    AvlTree<file_info_node> file_cache;
  private:
    stash my_stash;
    AvlTree<path_info_node> path_cache;
    char root_dir[MAX_DIRECTORY_LENGTH];
    char level_dir[MAX_DIRECTORY_LENGTH];
    char host_prefix[8];
    pstring level_context;
    int first_search_stash;
    int second_search_stash;
    bool stash_auto_build;
    bool file_system_locked;
    bool write_level_cache(os_file &sfl);
    void write_level_cache_tree(os_file &fp, os_file &sfl, TreeNode<file_info_node> *curr);
};

bool file_manager::write_level_cache(os_file &sfl)
{
  os_file fp;
  bool ret_val = false;

  stringx cache_filename(root_dir);
  cache_filename += level_dir;
  cache_filename += level_context.c_str();
  cache_filename += FILE_MANAGER_CACHE_EXTENSION;
  fp.open( cache_filename, os_file::FILE_WRITE );
  if (fp.is_open() == false)
    error("Could not write level files used cache");
  else
  {
    TreeNode<file_info_node> *root = file_cache.root();
    write_level_cache_tree(fp, sfl, root);
    fp.close();
    ret_val = true;
  }

  return ret_val;
}
